<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Policy\Filter;

use Throwable;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Service\Visibility\SmtpOutboundConfigRestrictFilterToVisibility;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TenantAccessible
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function __invoke(SmtpOutboundConfigRestrictFilterToVisibility $event): SmtpOutboundConfigRestrictFilterToVisibility
    {
        $this->logDebug("Check TenantAccessible Smtp outbound config");
        $span = $this->startSpan("Check TenantAccessible Smtp outbound config");
        try {
            $identity = $this->context->getIdentity();
            if (!($identity->hasScope("platform:global_access"))) {
                $event->with($event->smtpOutboundConfigFilter->withTenantAccessible($identity->getTenant()));
            }
            return $event;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
